    /// Every unattributed column of the statement: its id and its
    /// qualifier and name as written, in allocation order.
    fn unattributed(bindings: &BindingTable) -> Vec<(ColumnId, String)> {
        bindings
            .iter()
            .filter_map(|(id, binding)| match &binding.origin {
                ColumnOrigin::Unattributed {
                    qualifier, name, ..
                } => Some((
                    *id,
                    match qualifier {
                        Some(qualifier) => format!("{qualifier}.{name}"),
                        None => name.clone(),
                    },
                )),
                ColumnOrigin::Table { .. }
                | ColumnOrigin::Computed { .. }
                | ColumnOrigin::Merged { .. }
                | ColumnOrigin::SetOp { .. }
                | ColumnOrigin::OuterRef { .. }
                | ColumnOrigin::RecursiveRef { .. } => None,
            })
            .collect()
    }

    /// Every column a source or a DML target of `plan` lists, nested
    /// plans included.
    fn listed_by_sources(plan: &RelPlan) -> Vec<ColumnId> {
        struct Listed(Vec<ColumnId>);
        impl<'a> RelPlanVisitor<'a> for Listed {
            fn visit_rel_plan(&mut self, plan: &'a RelPlan) {
                match plan {
                    RelPlan::Scan { columns, .. }
                    | RelPlan::Values { columns, .. }
                    | RelPlan::ModelRef { columns, .. }
                    | RelPlan::DerivedTable { columns, .. } => self.0.extend(columns),
                    RelPlan::CteRef {
                        columns, demanded, ..
                    } => {
                        self.0.extend(columns);
                        self.0.extend(demanded.iter().map(|d| d.column));
                    }
                    RelPlan::TableFunction { output_columns, .. } => self.0.extend(output_columns),
                    RelPlan::Insert {
                        target_read_columns,
                        ..
                    }
                    | RelPlan::Update {
                        target_read_columns,
                        ..
                    }
                    | RelPlan::Delete {
                        target_read_columns,
                        ..
                    }
                    | RelPlan::Merge {
                        target_read_columns,
                        ..
                    } => self.0.extend(target_read_columns),
                    RelPlan::Project { .. }
                    | RelPlan::Filter { .. }
                    | RelPlan::Aggregate { .. }
                    | RelPlan::Window { .. }
                    | RelPlan::Join { .. }
                    | RelPlan::SetOp { .. }
                    | RelPlan::Sort { .. }
                    | RelPlan::Limit { .. }
                    | RelPlan::MultiInsert { .. }
                    | RelPlan::Explain { .. }
                    | RelPlan::CreateAsQuery { .. }
                    | RelPlan::CreateTableForm { .. }
                    | RelPlan::WithScope { .. }
                    | RelPlan::Unnest { .. }
                    | RelPlan::Pivot { .. }
                    | RelPlan::Unpivot { .. }
                    | RelPlan::MatchRecognize { .. }
                    | RelPlan::ConnectBy { .. }
                    | RelPlan::TableSample { .. }
                    | RelPlan::InvalidInput { .. }
                    | RelPlan::ParseRecovery { .. }
                    | RelPlan::Opaque { .. } => {}
                }
                walk_rel_plan(self, plan);
            }
        }
        let mut listed = Listed(Vec::new());
        listed.visit_rel_plan(plan);
        listed.0
    }

    /// Checks that `src` has exactly the unattributed columns `names`,
    /// each under one id, and that no source or target lists any.
    fn assert_unattributed(src: &str, names: &[&str]) -> (RelPlan, BindingTable) {
        let (plan, bindings) = lower_with_bindings(src);
        let found = unattributed(&bindings);
        let found_names: Vec<&str> = found.iter().map(|(_, name)| name.as_str()).collect();
        assert_eq!(found_names, names, "{src}\n{plan:#?}");
        let listed = listed_by_sources(&plan);
        for (id, name) in &found {
            assert!(!listed.contains(id), "{src}: {name} is listed\n{plan:#?}");
        }
        (plan, bindings)
    }

    #[test]
    fn an_ambiguous_name_is_unattributed() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) =
            assert_unattributed("SELECT a FROM t1 JOIN t2 ON t1.k = t2.k", &["a"]);
        let RelPlan::Project { items, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let [ProjectItem::Expr(item)] = items.as_slice() else {
            panic!("expected one expression item, got {items:#?}");
        };
        assert_eq!(
            columns_read(&item.expr),
            vec![unattributed(&bindings)[0].0],
            "{plan:#?}"
        );
    }

    #[test]
    fn a_block_has_one_unattributed_id_per_qualifier_and_name() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) = assert_unattributed(
            "SELECT a, zz.a AS b, ZZ.A AS c, yy.a AS d FROM t1 JOIN t2 ON t1.k = t2.k WHERE a > 0",
            &["a", "zz.a", "yy.a"],
        );
        let ids: Vec<ColumnId> = unattributed(&bindings).iter().map(|(id, _)| *id).collect();
        let RelPlan::Project { items, input, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let RelPlan::Filter { predicate, .. } = input.as_ref() else {
            panic!("expected Filter under the Project, got {input:#?}");
        };
        let mut reads = columns_read(predicate);
        for item in items {
            if let ProjectItem::Expr(item) = item {
                reads.extend(columns_read(&item.expr));
            }
        }
        assert_eq!(
            reads,
            vec![ids[0], ids[0], ids[1], ids[1], ids[2]],
            "{plan:#?}"
        );
        // Two pseudo rows of a trigger are two columns.
        assert_unattributed(
            "UPDATE audit SET n = 1 WHERE OLD.total = 1 AND NEW.total = 2",
            &["OLD.total", "NEW.total"],
        );
        // So are two dotted paths that end in one name and start with no
        // source, and one path written twice is one column.
        assert_unattributed(
            "SELECT a.id FROM t a JOIN t b ON a.id = b.id \
             WHERE x.addr.zip = 1 AND y.addr.zip = 2 AND X.ADDR.zip > 0",
            &["x.addr.zip", "y.addr.zip"],
        );
    }

    #[test]
    fn a_catalog_attributes_it() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, _catalog_ctx, bindings) = lower_with_catalog_tables(
            "SELECT a FROM analytics.public.t1 JOIN analytics.public.t2 ON t1.k = t2.k",
            &[("T1", &["K"]), ("T2", &["K", "A"])],
        );
        assert_eq!(unattributed(&bindings), vec![], "{plan:#?}");
        let RelPlan::Project { items, input, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let [ProjectItem::Expr(item)] = items.as_slice() else {
            panic!("expected one expression item, got {items:#?}");
        };
        let RelPlan::Join { right, .. } = input.as_ref() else {
            panic!("expected a Join under the Project, got {input:#?}");
        };
        let RelPlan::Scan {
            columns, node_id, ..
        } = right.as_ref()
        else {
            panic!("expected a Scan on the right, got {right:#?}");
        };
        let [a] = columns_read(&item.expr)[..] else {
            panic!("expected one column read, got {:#?}", item.expr);
        };
        assert_eq!(table_node_of(a, &bindings), *node_id, "{plan:#?}");
        assert!(columns.contains(&a), "{plan:#?}");
    }

    #[test]
    fn a_natural_joins_common_column_is_unattributed_where_the_tables_columns_are_not_known() {
        let _folding = crate::ir::normalize::default_folding();
        assert_unattributed("SELECT id FROM users NATURAL JOIN orders", &["id"]);
        // A catalog that declares both tables says which names they
        // share: the name reads the column the join merges.
        let (plan, _, bindings) = lower_with_catalog_tables(
            "SELECT id FROM analytics.public.users NATURAL JOIN analytics.public.orders",
            &[("USERS", &["ID", "NAME"]), ("ORDERS", &["ID", "TOTAL"])],
        );
        assert!(unattributed(&bindings).is_empty(), "{plan:#?}");
        let RelPlan::Project { input, items, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let RelPlan::Join { using, .. } = input.as_ref() else {
            panic!("expected Join, got {input:#?}");
        };
        let [merged] = using.as_slice() else {
            panic!("expected one merged column: {plan:#?}");
        };
        let [ProjectItem::Expr(item)] = items.as_slice() else {
            panic!("expected one item: {plan:#?}");
        };
        assert!(
            matches!(&item.expr, ScalarExpr::Column { column, .. } if *column == merged.merged),
            "{plan:#?}"
        );
        // The join reads the column of each table it merges.
        let listed = listed_by_sources(&plan);
        assert!(
            listed.contains(&merged.left) && listed.contains(&merged.right),
            "{plan:#?}"
        );
    }

