    #[test]
    fn a_from_item_answers_before_the_target() {
        let _folding = crate::ir::normalize::default_folding();
        // The join chain lowers `tbl a` as a source of the block: the
        // alias is that source's.
        let mssql = crate::dialect::mssql();
        let plan = lower_with_dialect(
            "DELETE a FROM tbl a JOIN b ON b.id = a.id \
             WHERE EXISTS (SELECT 1 FROM o WHERE o.k = a.y)",
            mssql.as_ref(),
        );
        let RelPlan::Delete {
            target_read_columns,
            using: Some(using),
            ..
        } = &plan
        else {
            panic!("expected Delete with a join chain, got {plan:#?}");
        };
        let RelPlan::Join { left, .. } = using.as_ref() else {
            panic!("expected a Join, got {using:#?}");
        };
        let RelPlan::Scan { columns, .. } = left.as_ref() else {
            panic!("expected a Scan on the left, got {left:#?}");
        };
        let [(1, column)] = outer_refs(&plan)[..] else {
            panic!("expected one correlated read: {plan:#?}");
        };
        assert!(columns.contains(&column), "{plan:#?}");
        assert!(target_read_columns.is_empty(), "{plan:#?}");
    }

    /// The columns of the one branch of a `MERGE`, an action over every
    /// target column; the `MERGE` may sit under a `WITH`.
    fn star_action_columns(plan: &RelPlan) -> &[MergeStarColumn] {
        let merge = if let RelPlan::WithScope { body, .. } = plan {
            body.as_ref()
        } else {
            plan
        };
        let RelPlan::Merge { branches, .. } = merge else {
            panic!("expected Merge, got {merge:#?}");
        };
        let [MergeBranch {
            action:
                MergeAction::UpdateSetStar { columns }
                | MergeAction::InsertStar { columns }
                | MergeAction::UpdateAllByName { columns }
                | MergeAction::InsertAllByName { columns },
            ..
        }] = branches.as_slice()
        else {
            panic!("expected one branch over every column, got {branches:#?}");
        };
        columns
    }

    /// The display names of the source columns the action's columns
    /// take, `None` where one takes none.
    fn taken_names(columns: &[MergeStarColumn], bindings: &BindingTable) -> Vec<Option<String>> {
        columns
            .iter()
            .map(|c| {
                c.source
                    .and_then(|id| bindings.get(id))
                    .map(|b| b.display_name.clone())
            })
            .collect()
    }

    #[test]
    fn a_star_action_pairs_a_derived_tables_columns_by_name() {
        let _folding = crate::ir::normalize::default_folding();
        // The source lists `name` before `id`; the target declares `id`
        // first.
        let (plan, _catalog_ctx, bindings) = lower_with_users_catalog_and_bindings(
            "MERGE INTO analytics.public.users t USING (SELECT x AS name, y AS id FROM staging) s \
             ON t.id = s.id WHEN MATCHED THEN UPDATE SET *",
        );
        let RelPlan::Merge { source, .. } = &plan else {
            panic!("expected Merge, got {plan:#?}");
        };
        let RelPlan::DerivedTable {
            columns: listed, ..
        } = source.as_ref()
        else {
            panic!("expected a DerivedTable, got {source:#?}");
        };
        let columns = star_action_columns(&plan);
        let taken: Vec<Option<ColumnId>> = columns.iter().map(|c| c.source).collect();
        assert_eq!(taken, vec![Some(listed[1]), Some(listed[0])], "{plan:#?}");
        assert_eq!(
            taken_names(columns, &bindings),
            vec![Some("ID".to_string()), Some("NAME".to_string())],
            "{plan:#?}"
        );
    }

    #[test]
    fn a_star_action_takes_nothing_for_a_column_a_narrower_source_lacks() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, _catalog_ctx, bindings) = lower_with_users_catalog_and_bindings(
            "WITH c AS (SELECT y AS id FROM staging) \
             MERGE INTO analytics.public.users t USING c \
             ON t.id = c.id WHEN NOT MATCHED THEN INSERT *",
        );
        let columns = star_action_columns(&plan);
        let written: Vec<ColumnId> = columns.iter().map(|c| c.written).collect();
        assert_eq!(
            display_names(&written, &bindings),
            vec!["ID", "NAME"],
            "{plan:#?}"
        );
        assert_eq!(
            taken_names(columns, &bindings),
            vec![Some("ID".to_string()), None],
            "{plan:#?}"
        );
    }

