    /// The `Project` over a two-scan `Join`: its items, the join's
    /// `USING` columns, and what each scan lists.
    fn using_join(plan: &RelPlan) -> (&[ProjectItem], &[UsingColumn], &[ColumnId], &[ColumnId]) {
        let RelPlan::Project { input, items, .. } = plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let RelPlan::Join {
            left, right, using, ..
        } = input.as_ref()
        else {
            panic!("expected Join under the Project, got {input:#?}");
        };
        let (RelPlan::Scan { columns: left, .. }, RelPlan::Scan { columns: right, .. }) =
            (left.as_ref(), right.as_ref())
        else {
            panic!("expected two Scans under the Join, got {input:#?}");
        };
        (items, using, left, right)
    }

    #[test]
    fn a_using_column_names_both_sides() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower("SELECT id, amount FROM users u JOIN orders o USING (id)");
        let (items, using, users, orders) = using_join(&plan);
        let [column] = using else {
            panic!("expected one USING column, got {using:#?}");
        };
        assert!(users.contains(&column.left), "{plan:#?}");
        assert!(orders.contains(&column.right), "{plan:#?}");
        let ProjectItem::Expr(id) = &items[0] else {
            panic!("expected an expression item, got {items:#?}");
        };
        assert_eq!(columns_read(&id.expr), vec![column.merged], "{plan:#?}");
    }

    #[test]
    fn a_using_column_is_paired_in_either_order() {
        let _folding = crate::ir::normalize::default_folding();
        for (sql, derived_on_the_left) in [
            (
                "SELECT id FROM users b LEFT JOIN (SELECT user_id AS id FROM orders) a USING (id)",
                false,
            ),
            (
                "SELECT id FROM (SELECT user_id AS id FROM orders) a LEFT JOIN users b USING (id)",
                true,
            ),
        ] {
            let plan = lower(sql);
            let RelPlan::Project { input, items, .. } = &plan else {
                panic!("expected Project, got {plan:#?}");
            };
            let RelPlan::Join {
                left, right, using, ..
            } = input.as_ref()
            else {
                panic!("expected Join under the Project, got {input:#?}");
            };
            let [column] = using.as_slice() else {
                panic!("{sql}: expected one USING column, got {using:#?}");
            };
            let (derived, scan, of_derived, of_scan) = if derived_on_the_left {
                (left, right, column.left, column.right)
            } else {
                (right, left, column.right, column.left)
            };
            let RelPlan::DerivedTable { columns, .. } = derived.as_ref() else {
                panic!("{sql}: expected a derived table, got {derived:#?}");
            };
            assert_eq!(columns, &[of_derived], "{sql}");
            let RelPlan::Scan { columns, .. } = scan.as_ref() else {
                panic!("{sql}: expected a scan, got {scan:#?}");
            };
            assert_eq!(columns, &[of_scan], "{sql}");
            let ProjectItem::Expr(id) = &items[0] else {
                panic!("expected an expression item, got {items:#?}");
            };
            assert_eq!(columns_read(&id.expr), vec![column.merged], "{sql}");
        }
    }

    #[test]
    fn each_using_name_pairs_its_own_columns() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower("SELECT a, b FROM t JOIN u USING (a, b)");
        let (items, using, on_t, on_u) = using_join(&plan);
        let [first, second] = using else {
            panic!("expected two USING columns, got {using:#?}");
        };
        assert_eq!(on_t, &[first.left, second.left], "{plan:#?}");
        assert_eq!(on_u, &[first.right, second.right], "{plan:#?}");
        let reads: Vec<Vec<ColumnId>> = items
            .iter()
            .map(|item| match item {
                ProjectItem::Expr(e) => columns_read(&e.expr),
                ProjectItem::Star(_) => panic!("expected expression items, got {items:#?}"),
            })
            .collect();
        assert_eq!(
            reads,
            vec![vec![first.merged], vec![second.merged]],
            "{plan:#?}"
        );
    }

    #[test]
    fn a_using_side_that_is_a_cte_reference_is_its_column() {
        let _folding = crate::ir::normalize::default_folding();
        let plan =
            lower("WITH c AS (SELECT id FROM users) SELECT id FROM c JOIN orders o USING (id)");
        let RelPlan::WithScope { body, .. } = &plan else {
            panic!("expected WithScope, got {plan:#?}");
        };
        let RelPlan::Project { input, .. } = body.as_ref() else {
            panic!("expected Project, got {body:#?}");
        };
        let RelPlan::Join {
            left, right, using, ..
        } = input.as_ref()
        else {
            panic!("expected Join under the Project, got {input:#?}");
        };
        let (RelPlan::CteRef { columns: on_c, .. }, RelPlan::Scan { columns: on_o, .. }) =
            (left.as_ref(), right.as_ref())
        else {
            panic!("expected a CteRef and a Scan under the Join, got {input:#?}");
        };
        let [column] = using.as_slice() else {
            panic!("expected one USING column, got {using:#?}");
        };
        assert_eq!(on_c, &vec![column.left], "{plan:#?}");
        assert_eq!(on_o, &vec![column.right], "{plan:#?}");
    }

    #[test]
    fn a_nested_using_join_gives_its_merged_column() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower("SELECT id FROM a JOIN b USING (id) JOIN c USING (id)");
        let RelPlan::Project { input, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let RelPlan::Join {
            left,
            right,
            using: outer,
            ..
        } = input.as_ref()
        else {
            panic!("expected Join under the Project, got {input:#?}");
        };
        let RelPlan::Join { using: inner, .. } = left.as_ref() else {
            panic!("expected a Join on the left, got {left:#?}");
        };
        let RelPlan::Scan { columns: on_c, .. } = right.as_ref() else {
            panic!("expected a Scan on the right, got {right:#?}");
        };
        let ([outer], [inner]) = (outer.as_slice(), inner.as_slice()) else {
            panic!("expected one USING column per join: {input:#?}");
        };
        assert_eq!(outer.left, inner.merged, "{plan:#?}");
        assert_eq!(on_c, &vec![outer.right], "{plan:#?}");
        assert_eq!(
            columns_read(single_item_expr(&plan)),
            vec![outer.merged],
            "{plan:#?}"
        );
    }

    #[test]
    fn a_qualified_reference_beside_using_is_the_sides_column() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower("SELECT u.id FROM users u JOIN orders o USING (id)");
        let (items, using, _, _) = using_join(&plan);
        let [column] = using else {
            panic!("expected one USING column, got {using:#?}");
        };
        let [ProjectItem::Expr(id)] = items else {
            panic!("expected one expression item, got {items:#?}");
        };
        assert_eq!(columns_read(&id.expr), vec![column.left], "{plan:#?}");
    }

    #[test]
    fn a_scan_in_a_scalar_subquery_is_seeded() {
        let _folding = crate::ir::normalize::default_folding();
        use crate::catalog::{
            CatalogColumn, CatalogDatabase, CatalogIdent, CatalogSchema, CatalogSnapshot,
            CatalogTable, CatalogTableKind,
        };
        let column = |name: &str| CatalogColumn {
            name: CatalogIdent {
                name: name.to_string(),
            },
            data_type: Some("NUMBER".to_string()),
            nullable: Some(true),
            tags: vec![],
        };
        let table = |name: &str, columns: Vec<CatalogColumn>| CatalogTable {
            name: CatalogIdent {
                name: name.to_string(),
            },
            kind: CatalogTableKind::Table,
            columns,
            row_count_estimate: None,
            row_count_estimate_as_of: None,
            bytes_estimate: None,
            bytes_estimate_as_of: None,
            constraints: vec![],
            comment: None,
            tags: vec![],
        };
        let snapshot = CatalogSnapshot {
            schema_version: crate::CATALOG_SCHEMA_VERSION,
            listing: crate::catalog::CatalogListing::Inventory,
            generated_at: None,
            source: Some("scalar-subquery-seed-test".to_string()),
            policies: vec![],
            policy_references: vec![],
            grants: None,
            provider: None,
            databases: vec![CatalogDatabase {
                name: CatalogIdent {
                    name: "ANALYTICS".to_string(),
                },
                schemas: vec![CatalogSchema {
                    name: CatalogIdent {
                        name: "PUBLIC".to_string(),
                    },
                    tables: vec![
                        table("USERS", vec![column("ID")]),
                        table("ORDERS", vec![column("AMOUNT")]),
                    ],
                }],
            }],
        };
        let catalog = CatalogIndex::from_snapshot(snapshot).expect("valid catalog");
        let src = "SELECT (SELECT MAX(o.amount) FROM analytics.public.orders o) AS m \
                   FROM analytics.public.users u";
        let stmt = parse_one(src);
        let functions = FunctionCatalog::for_dialect(CatalogDialect::Default);
        let session = SessionContext::default();
        let (plan, catalog_ctx, bindings, _facts) = lower_query_full_with_bindings(
            &stmt,
            src,
            StrictMode::Permissive,
            &functions,
            &session,
            Some(&catalog),
        )
        .expect("lower");
        let ScalarExpr::ScalarSubquery { subquery, .. } = single_item_expr(&plan) else {
            panic!("expected a scalar subquery item: {plan:#?}");
        };
        let RelPlan::Project { input, .. } = subquery.as_ref() else {
            panic!("expected Project in the subquery, got {subquery:#?}");
        };
        let RelPlan::Aggregate { input, .. } = input.as_ref() else {
            panic!("expected Aggregate in the subquery, got {input:#?}");
        };
        let RelPlan::Scan { columns, .. } = input.as_ref() else {
            panic!("expected Scan in the subquery, got {input:#?}");
        };
        let amount = columns
            .iter()
            .copied()
            .find(|c| bindings.get(*c).is_some_and(|b| b.display_name == "AMOUNT"))
            .unwrap_or_else(|| panic!("the nested scan lists no AMOUNT: {plan:#?}"));
        assert!(
            super::super::catalog_context::CatalogContext::column_metadata(&catalog_ctx, amount)
                .is_some(),
            "no catalog metadata for the nested scan's AMOUNT"
        );
    }

    #[test]
    fn the_first_references_span_is_the_origins() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) =
            lower_with_bindings("SELECT u.email FROM users u WHERE u.email IS NOT NULL");
        let ScalarExpr::Column {
            column,
            span: projected_span,
        } = single_item_expr(&plan)
        else {
            panic!("expected a column item: {plan:#?}");
        };
        let ColumnOrigin::Table { span, .. } = &bindings.get(*column).expect("binding").origin
        else {
            panic!("expected a table origin: {bindings:#?}");
        };
        assert_eq!(span, projected_span);
        let RelPlan::Project { input, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let RelPlan::Filter { predicate, .. } = input.as_ref() else {
            panic!("expected Filter under the Project, got {input:#?}");
        };
        struct Spans(Vec<Span>);
        impl<'a> ScalarExprVisitor<'a> for Spans {
            fn visit_scalar_expr(&mut self, expr: &'a ScalarExpr) {
                if let ScalarExpr::Column { span, .. } = expr {
                    self.0.push(*span);
                }
                walk_scalar_expr_standalone(self, expr);
            }
        }
        let mut spans = Spans(Vec::new());
        spans.visit_scalar_expr(predicate);
        let [filter_span] = spans.0[..] else {
            panic!("expected the filter to read one column: {predicate:#?}");
        };
        assert_ne!(&filter_span, projected_span);
        assert!(filter_span.start > projected_span.start, "{predicate:#?}");
    }

    /// The bindings and the body of a `WithScope` root.
    fn with_scope(plan: &RelPlan) -> (&[CteBinding], &RelPlan) {
        let RelPlan::WithScope { ctes, body, .. } = plan else {
            panic!("expected WithScope, got {plan:#?}");
        };
        (ctes, body)
    }

    /// The columns of the only `Scan` under `plan`, which must be one.
    fn only_scan_columns(plan: &RelPlan) -> &[ColumnId] {
        struct Scans<'p>(Vec<&'p [ColumnId]>);
        impl<'p> RelPlanVisitor<'p> for Scans<'p> {
            fn visit_rel_plan(&mut self, plan: &'p RelPlan) {
                if let RelPlan::Scan { columns, .. } = plan {
                    self.0.push(columns);
                }
                walk_rel_plan(self, plan);
            }
        }
        let mut scans = Scans(Vec::new());
        scans.visit_rel_plan(plan);
        let [columns] = scans.0[..] else {
            panic!("expected one Scan, got {plan:#?}");
        };
        columns
    }

    /// The scan column named `name` among `columns`.
    fn scan_column(columns: &[ColumnId], bindings: &BindingTable, name: &str) -> ColumnId {
        columns
            .iter()
            .copied()
            .find(|c| {
                bindings
                    .get(*c)
                    .is_some_and(|b| b.display_name.eq_ignore_ascii_case(name))
            })
            .unwrap_or_else(|| panic!("no scan column named {name} among {columns:?}"))
    }

    /// The `CteRef` the only `Project` of `body` reads from, and the
    /// column its only item reads.
    fn reference_and_read(body: &RelPlan) -> (&RelPlan, ColumnId) {
        let RelPlan::Project { input, .. } = body else {
            panic!("expected Project, got {body:#?}");
        };
        let [read] = columns_read(single_item_expr(body))[..] else {
            panic!("expected one column read, got {body:#?}");
        };
        (input.as_ref(), read)
    }

    #[test]
    fn a_star_cte_column_is_the_references_own() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) =
            lower_with_bindings("WITH c AS (SELECT * FROM users) SELECT x.name FROM c x");
        let (ctes, body) = with_scope(&plan);
        let (reference, read) = reference_and_read(body);
        let RelPlan::CteRef {
            demanded, node_id, ..
        } = reference
        else {
            panic!("expected a CteRef under the Project, got {reference:#?}");
        };
        let Some(ColumnOrigin::Computed { producing_node, .. }) =
            bindings.get(read).map(|b| &b.origin)
        else {
            panic!("expected a computed column, got {:#?}", bindings.get(read));
        };
        assert_eq!(producing_node, node_id, "{plan:#?}");
        let [demand] = demanded.as_slice() else {
            panic!("expected one demanded column, got {demanded:#?}");
        };
        assert_eq!(demand.column, read, "{plan:#?}");
        let name = scan_column(only_scan_columns(&plan), &bindings, "name");
        assert_eq!(
            ctes[0].slot_columns.get(demand.slot as usize),
            Some(&Some(name)),
            "{plan:#?}"
        );
    }

    #[test]
    fn two_references_get_two_columns() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) = lower_with_bindings(
            "WITH c AS (SELECT * FROM users) \
             SELECT x.name, y.name AS yn FROM c x LEFT JOIN c y ON y.id = x.id",
        );
        let (ctes, body) = with_scope(&plan);
        let RelPlan::Project { input, items, .. } = body else {
            panic!("expected Project, got {body:#?}");
        };
        let RelPlan::Join { left, right, .. } = input.as_ref() else {
            panic!("expected a Join under the Project, got {input:#?}");
        };
        let (RelPlan::CteRef { demanded: on_x, .. }, RelPlan::CteRef { demanded: on_y, .. }) =
            (left.as_ref(), right.as_ref())
        else {
            panic!("expected two CteRefs under the Join, got {input:#?}");
        };
        let reads: Vec<ColumnId> = items
            .iter()
            .filter_map(|item| match item {
                ProjectItem::Expr(e) => columns_read(&e.expr).first().copied(),
                ProjectItem::Star(_) => None,
            })
            .collect();
        let [x_name, y_name] = reads[..] else {
            panic!("expected two column reads, got {items:#?}");
        };
        assert_ne!(x_name, y_name, "{plan:#?}");
        let slot_of = |demanded: &[DemandedColumn], column: ColumnId| {
            demanded
                .iter()
                .find(|d| d.column == column)
                .map(|d| d.slot)
                .unwrap_or_else(|| panic!("{column:?} is not demanded in {demanded:#?}"))
        };
        let slot = slot_of(on_x, x_name);
        assert_eq!(slot, slot_of(on_y, y_name), "{plan:#?}");
        let name = scan_column(only_scan_columns(&plan), &bindings, "name");
        assert_eq!(
            ctes[0].slot_columns.get(slot as usize),
            Some(&Some(name)),
            "{plan:#?}"
        );
    }

    #[test]
    fn a_demanded_column_does_not_become_a_star_column() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) = lower_with_bindings(
            "WITH a AS (SELECT * FROM t), b AS (SELECT a.x FROM a) SELECT * FROM a",
        );
        let (ctes, body) = with_scope(&plan);
        let RelPlan::Project { input, items, .. } = body else {
            panic!("expected Project, got {body:#?}");
        };
        // The star makes no item of `x` and stays open.
        let [ProjectItem::Star(star)] = items.as_slice() else {
            panic!("expected the star alone, got {plan:#?}");
        };
        assert!(!star.complete && star.enumerated.is_empty(), "{plan:#?}");
        let RelPlan::CteRef {
            columns, demanded, ..
        } = input.as_ref()
        else {
            panic!("expected a CteRef under the Project, got {input:#?}");
        };
        assert!(columns.is_empty(), "{plan:#?}");
        // `b`'s read makes `x` a known column of `a`'s body: the star reads
        // it through the reference, as a demand of the reference's own.
        let [DemandedColumn { slot, .. }] = demanded.as_slice() else {
            panic!("expected one demanded column, got {plan:#?}");
        };
        let x = scan_column(only_scan_columns(&plan), &bindings, "x");
        assert_eq!(
            ctes[0].slot_columns.get(*slot as usize),
            Some(&Some(x)),
            "{plan:#?}"
        );
    }

    #[test]
    fn a_name_one_source_is_read_qualified_of_is_that_sources_column_through_a_star() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) = lower_with_bindings(
            "WITH c AS (SELECT * FROM t1 JOIN t2 ON t1.id = t2.id WHERE t1.x > 5) \
             SELECT x FROM c",
        );
        let (ctes, body) = with_scope(&plan);
        let (reference, read) = reference_and_read(body);
        let RelPlan::CteRef { demanded, .. } = reference else {
            panic!("expected a CteRef under the Project, got {reference:#?}");
        };
        let slot = demanded
            .iter()
            .find(|d| d.column == read)
            .map(|d| d.slot)
            .unwrap_or_else(|| panic!("{read:?} is not demanded: {plan:#?}"));
        let paired = ctes[0]
            .slot_columns
            .get(slot as usize)
            .copied()
            .flatten()
            .unwrap_or_else(|| panic!("`x` is paired with no column: {plan:#?}"));
        struct Scans(Vec<(String, crate::ast::NodeId)>);
        impl<'p> RelPlanVisitor<'p> for Scans {
            fn visit_rel_plan(&mut self, plan: &'p RelPlan) {
                if let RelPlan::Scan { table, node_id, .. } = plan {
                    self.0.push((table.name.clone(), *node_id));
                }
                walk_rel_plan(self, plan);
            }
        }
        let mut scans = Scans(Vec::new());
        scans.visit_rel_plan(&plan);
        let t1 = scans
            .0
            .iter()
            .find(|(name, _)| name == "t1")
            .map(|(_, node)| *node)
            .expect("the scan of t1");
        let Some(ColumnOrigin::Table {
            table_node,
            column_name,
            ..
        }) = bindings.get(paired).map(|b| &b.origin)
        else {
            panic!("`x` is paired with no table column: {plan:#?}");
        };
        assert_eq!((*table_node, column_name.as_str()), (t1, "x"), "{plan:#?}");
    }

    #[test]
    fn a_chain_of_star_ctes_demands_through() {
        let _folding = crate::ir::normalize::default_folding();
        let (plan, bindings) = lower_with_bindings(
            "WITH a AS (SELECT * FROM t), b AS (SELECT * FROM a) SELECT b.x FROM b",
        );
        let [root] = plan.output_schema()[..] else {
            panic!("expected one output column, got {plan:#?}");
        };
        let x = scan_column(only_scan_columns(&plan), &bindings, "x");
        assert_eq!(
            super::super::pairing::source_column(&plan, root),
            Some(x),
            "{plan:#?}"
        );
    }

