    #[test]
    fn each_item_of_an_update_from_list_has_its_own_id() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower(
            "UPDATE users SET name = a.amount FROM orders a, orders b \
             WHERE a.id = users.id AND b.user_id = users.id",
        );
        let RelPlan::Update {
            from: Some(from),
            node_id,
            ..
        } = &plan
        else {
            panic!("expected Update with FROM, got {plan:#?}");
        };
        let RelPlan::Join { left, right, .. } = from.as_ref() else {
            panic!("expected the FROM list to be a Join, got {from:#?}");
        };
        let (RelPlan::Scan { node_id: a, .. }, RelPlan::Scan { node_id: b, .. }) =
            (left.as_ref(), right.as_ref())
        else {
            panic!("expected two Scans, got {from:#?}");
        };
        assert_ne!(a, b, "the two FROM items share a node id");
        assert_ne!(a, node_id, "a FROM item carries the statement's id");
        assert_ne!(b, node_id, "a FROM item carries the statement's id");
    }

