    #[test]
    fn having_lowers_onto_aggregate_node() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower("SELECT a, COUNT(*) FROM t GROUP BY a HAVING COUNT(*) > 1");
        let agg = unwrap_project_agg(plan);
        match agg {
            RelPlan::Aggregate {
                aggregates, having, ..
            } => {
                // The same textual `COUNT(*)` appears in projection
                // and in HAVING; lowering collects them as *two
                // occurrences* (distinct spans, distinct output ids).
                // Structurally-equal calls are not merged; the
                // assertion below pins current behavior so a
                // canonicalization change is intentional.
                assert_eq!(
                    aggregates.len(),
                    2,
                    "identical aggregate calls are not canonicalized"
                );
                assert!(having.is_some());
            }
            other => panic!("expected Aggregate, got {:?}", other),
        }
    }

    #[test]
    fn cube_rollup_and_grouping_sets_preserve_shape() {
        let _folding = crate::ir::normalize::default_folding();
        let cube = unwrap_project_agg(lower("SELECT a, b, SUM(c) FROM t GROUP BY CUBE (a, b)"));
        match cube {
            RelPlan::Aggregate { grouping, .. } => {
                assert!(matches!(grouping, GroupingSpec::Cube(ref k) if k.len() == 2));
            }
            other => panic!("expected Aggregate, got {:?}", other),
        }

        let rollup = unwrap_project_agg(lower("SELECT a, b, SUM(c) FROM t GROUP BY ROLLUP (a, b)"));
        match rollup {
            RelPlan::Aggregate { grouping, .. } => {
                assert!(matches!(grouping, GroupingSpec::Rollup(ref k) if k.len() == 2));
            }
            other => panic!("expected Aggregate, got {:?}", other),
        }

        let sets = unwrap_project_agg(lower(
            "SELECT a, b, SUM(c) FROM t GROUP BY GROUPING SETS ((a), (a, b))",
        ));
        match sets {
            RelPlan::Aggregate { grouping, .. } => {
                assert!(matches!(grouping, GroupingSpec::GroupingSets(ref s) if s.sets.len() == 2));
            }
            other => panic!("expected Aggregate, got {:?}", other),
        }
    }

    #[test]
    fn group_by_ordinal_resolves_to_projection_item() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower("SELECT a, COUNT(*) FROM t GROUP BY 1");
        let agg = unwrap_project_agg(plan);
        match agg {
            RelPlan::Aggregate {
                grouping,
                aggregates,
                ..
            } => {
                let keys = match grouping {
                    GroupingSpec::Standard(k) => k,
                    other => panic!("expected Standard, got {:?}", other),
                };
                assert_eq!(keys.len(), 1);
                // The key holds the first item's column reference.
                match &keys[0].expr {
                    ScalarExpr::Column { .. } => {}
                    other => panic!("expected Column expr, got {:?}", other),
                }
                assert_eq!(aggregates.len(), 1);
            }
            other => panic!("expected Aggregate, got {:?}", other),
        }
    }

    #[test]
    fn group_by_ordinal_out_of_range_errors() {
        let _folding = crate::ir::normalize::default_folding();
        // An ordinal that exceeds the projection width is out of range.
        // Per the comment at `try_resolve_group_by_ordinal` (line ~7709),
        // the lowerer intentionally falls through to scalar lowering
        // rather than producing `InvalidInput` — emitting `InvalidInput`
        // would discard all table/column information from the statement.
        // The result is a valid `Project → Aggregate` plan whose group
        // key is a `ScalarExpr::Opaque` (positional ref, unresolvable).
        let src = "SELECT a FROM t GROUP BY 5";
        let stmt = parse_one(src);
        let plan = lower_query(&stmt, src, StrictMode::Strict)
            .expect("out-of-range ordinal lowers to a valid plan, not LowerError");
        // Should produce a relational plan (Project/Aggregate), not InvalidInput.
        assert!(
            !matches!(plan, RelPlan::InvalidInput { .. }),
            "out-of-range GROUP BY ordinal must not produce InvalidInput (see \
             try_resolve_group_by_ordinal fallthrough): got {:?}",
            plan
        );
        assert!(
            !matches!(plan, RelPlan::Opaque { .. }),
            "out-of-range GROUP BY ordinal must not produce Opaque: got {:?}",
            plan
        );
    }

    /// The keys of the plain `GROUP BY` under the projection `plan`.
    fn standard_keys(plan: RelPlan) -> Vec<GroupKey> {
        match unwrap_project_agg(plan) {
            RelPlan::Aggregate {
                grouping: GroupingSpec::Standard(keys),
                ..
            } => keys,
            other => panic!("expected an Aggregate with a plain grouping, got {other:#?}"),
        }
    }

    fn is_unresolved_position(key: &GroupKey) -> bool {
        matches!(
            &key.expr,
            ScalarExpr::Opaque { reason, .. } if reason == "group_by_position_unresolved"
        )
    }

    #[test]
    fn an_unresolved_position_is_no_constant_key() {
        let _folding = crate::ir::normalize::default_folding();
        // The star's columns cannot be counted: position 1 is one of them.
        let keys = standard_keys(lower("SELECT *, COUNT(*) AS n FROM users GROUP BY 1"));
        let [key] = keys.as_slice() else {
            panic!("expected one key, got {keys:#?}");
        };
        assert!(is_unresolved_position(key), "{key:#?}");

        // With the star's columns listed, position 1 is the first of them.
        let (plan, _, bindings) = lower_with_catalog_tables(
            "SELECT *, COUNT(*) AS n FROM analytics.public.users GROUP BY 1",
            &[("USERS", &["ID", "NAME"])],
        );
        let keys = standard_keys(plan);
        let [key] = keys.as_slice() else {
            panic!("expected one key, got {keys:#?}");
        };
        let ScalarExpr::Column { column, .. } = &key.expr else {
            panic!("expected a column key, got {key:#?}");
        };
        let name = bindings.get(*column).map(|b| b.display_name.as_str());
        assert_eq!(name, Some("ID"));
    }

    #[test]
    fn a_position_past_an_uncounted_star_is_unresolved() {
        let _folding = crate::ir::normalize::default_folding();
        // `nm` is the second item lowered, and no one knows which column
        // of the select list it is.
        for sql in [
            "SELECT *, name AS nm, COUNT(*) AS n FROM users GROUP BY 2",
            "SELECT *, name AS nm, COUNT(*) AS n FROM (SELECT *, a FROM t) d GROUP BY 1",
        ] {
            let keys = standard_keys(lower(sql));
            let [key] = keys.as_slice() else {
                panic!("expected one key, got {keys:#?}");
            };
            assert!(is_unresolved_position(key), "{sql}: {key:#?}");
        }
        // A position before the star is counted.
        let keys = standard_keys(lower(
            "SELECT name AS nm, *, COUNT(*) AS n FROM users GROUP BY 1",
        ));
        assert!(
            matches!(keys.as_slice(), [key] if matches!(key.expr, ScalarExpr::Column { .. })),
            "{keys:#?}"
        );
    }

    #[test]
    fn a_listed_star_is_no_position_of_its_own() {
        let _folding = crate::ir::normalize::default_folding();
        // `ID`, `NAME`, then `nm`: the third column.
        let (plan, _, _) = lower_with_catalog_tables(
            "SELECT *, UPPER(name) AS nm, COUNT(*) AS n FROM analytics.public.users GROUP BY 3",
            &[("USERS", &["ID", "NAME"])],
        );
        let RelPlan::Project { items, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let nm = items
            .iter()
            .find_map(|item| match item {
                ProjectItem::Expr(e) if e.alias.as_ref().is_some_and(|a| a.as_str() == "NM") => {
                    Some(e)
                }
                ProjectItem::Expr(_) | ProjectItem::Star(_) => None,
            })
            .expect("the item nm");
        let ScalarExpr::Column { column: read, .. } = &nm.expr else {
            panic!("expected nm to read its key, got {nm:#?}");
        };
        let read = *read;
        let keys = standard_keys(plan);
        let [key] = keys.as_slice() else {
            panic!("expected one key, got {keys:#?}");
        };
        assert_eq!(key.output, read);
        assert!(matches!(key.expr, ScalarExpr::FuncCall { .. }), "{key:#?}");
    }

    /// A grouped block: its select items, the key columns of its
    /// grouping, its aggregate calls, its `HAVING`, and the keys and
    /// window calls of the sort and window stages around it.
    struct GroupedBlock {
        items: Vec<ProjectItem>,
        grouping: GroupingSpec,
        aggregates: Vec<AggregateCall>,
        having: Option<ScalarExpr>,
        windows: Vec<WindowCall>,
        sort: Vec<SortKey>,
    }

    impl GroupedBlock {
        fn of(plan: RelPlan) -> Self {
            let (plan, sort) = match plan {
                RelPlan::Sort { input, keys, .. } => (*input, keys),
                other => (other, Vec::new()),
            };
            let RelPlan::Project { input, items, .. } = plan else {
                panic!("expected Project, got {plan:#?}");
            };
            let (input, windows) = match *input {
                RelPlan::Window { input, windows, .. } => (*input, windows),
                other => (other, Vec::new()),
            };
            let RelPlan::Aggregate {
                grouping,
                aggregates,
                having,
                ..
            } = input
            else {
                panic!("expected Aggregate, got {input:#?}");
            };
            Self {
                items,
                grouping,
                aggregates,
                having,
                windows,
                sort,
            }
        }

        fn lowered(src: &str) -> Self {
            Self::of(lower(src))
        }

        /// The grouping's keys, in the order held.
        fn keys(&self) -> &[GroupKey] {
            match &self.grouping {
                GroupingSpec::None => &[],
                GroupingSpec::Standard(keys)
                | GroupingSpec::Cube(keys)
                | GroupingSpec::Rollup(keys)
                | GroupingSpec::All { keys, .. } => keys,
                GroupingSpec::GroupingSets(sets) => &sets.keys,
            }
        }

        /// The expression of the item at `position`.
        fn item(&self, position: usize) -> &ScalarExpr {
            match &self.items[position] {
                ProjectItem::Expr(item) => &item.expr,
                ProjectItem::Star(star) => panic!("expected an expression item, got {star:#?}"),
            }
        }
    }

    /// Where the query wrote the key's expression again: the span of each
    /// occurrence the key keeps.
    fn written_at(key: &GroupKey) -> Vec<Span> {
        key.written_again.iter().map(ScalarExpr::span).collect()
    }

    /// Whether `expr` is a bare read of `column`.
    fn reads_only(expr: &ScalarExpr, column: ColumnId) -> bool {
        matches!(expr, ScalarExpr::Column { column: read, .. } if *read == column)
    }

    #[test]
    fn a_written_out_group_key_reads_its_key() {
        let _folding = crate::ir::normalize::default_folding();
        let src = "SELECT LOWER(name) AS k, COUNT(*) FROM users GROUP BY LOWER(name)";
        let (plan, bindings) = lower_with_bindings(src);
        let violations = crate::ir::plan_identity::check_plan_identity(&plan, &bindings);
        assert!(violations.is_empty(), "{violations:?}\n{plan:#?}");
        let block = GroupedBlock::of(plan);
        let [key] = block.keys() else {
            panic!("expected one key, got {:#?}", block.grouping);
        };
        assert!(matches!(key.expr, ScalarExpr::FuncCall { .. }), "{key:#?}");
        assert!(reads_only(block.item(0), key.output), "{:#?}", block.items);
        // The read stands where the query wrote the expression again.
        assert_eq!(written_at(key), vec![block.item(0).span()]);
        assert_eq!(slice_span(src, written_at(key)[0]), Some("LOWER(name)"));
        // What was written there: the call over the column, with the
        // spans of the select list.
        let [ScalarExpr::FuncCall { args, span, .. }] = key.written_again.as_slice() else {
            panic!("expected one call, got {:#?}", key.written_again);
        };
        assert_eq!(slice_span(src, *span), Some("LOWER(name)"));
        assert_eq!(slice_span(src, args[0].span()), Some("name"));
        assert!(args[0].span().end < key.expr.span().start);
        assert_eq!(columns_read(&args[0]), columns_read(&key.expr));
    }

    #[test]
    fn a_written_out_key_is_read_at_any_depth() {
        let _folding = crate::ir::normalize::default_folding();
        let block = GroupedBlock::lowered(
            "SELECT COALESCE(UPPER(LOWER(name)), 'Total') AS k, COUNT(*) FROM users \
             GROUP BY ROLLUP(LOWER(name))",
        );
        let [key] = block.keys() else {
            panic!("expected one key, got {:#?}", block.grouping);
        };
        let ScalarExpr::FuncCall { args: coalesce, .. } = block.item(0) else {
            panic!("expected COALESCE, got {:#?}", block.items);
        };
        let ScalarExpr::FuncCall { args: upper, .. } = &coalesce[0] else {
            panic!("expected UPPER, got {coalesce:#?}");
        };
        assert!(reads_only(&upper[0], key.output), "{upper:#?}");
        // No column of `users` is read above the grouping.
        assert_eq!(columns_read(block.item(0)), vec![key.output]);
        assert_eq!(written_at(key), vec![upper[0].span()]);
    }

