    #[test]
    fn a_star_replace_expression_is_held_by_its_item() {
        let _folding = crate::ir::normalize::default_folding();
        let plan = lower(
            "SELECT * REPLACE ((SELECT MAX(o.amount) FROM orders o) AS name) \
             FROM (SELECT id, name FROM users) u",
        );
        assert_eq!(nested_plan_count(&plan), 1, "{plan:#?}");
        let RelPlan::Project { items, .. } = &plan else {
            panic!("expected Project, got {plan:#?}");
        };
        let Some(ProjectItem::Star(star)) = items.last() else {
            panic!("expected the star last, got {items:#?}");
        };
        let [entry] = star.replace.as_slice() else {
            panic!("expected one REPLACE entry, got {:#?}", star.replace);
        };
        let holder = items.iter().find_map(|item| match item {
            ProjectItem::Expr(e) if matches!(e.expr, ScalarExpr::ScalarSubquery { .. }) => {
                Some(e.output)
            }
            ProjectItem::Expr(_) | ProjectItem::Star(_) => None,
        });
        assert!(
            matches!(entry.expr, ScalarExpr::Column { column, .. } if Some(column) == holder),
            "the entry does not read the item holding its expression: {plan:#?}"
        );
    }

    #[test]
    fn non_aggregate_function_call_in_projection_lowers() {
        let _folding = crate::ir::normalize::default_folding();
        // Generic FunctionCall lowering: a scalar call with
        // no aggregate shape and no GROUP BY must NOT synthesize an
        // Aggregate node.
        let plan = lower("SELECT UPPER(a) FROM t");
        match plan {
            RelPlan::Project { input, items, .. } => {
                assert_eq!(items.len(), 1);
                let ProjectItem::Expr(e0) = &items[0] else {
                    panic!("expected ProjectItem::Expr, got {:?}", items[0]);
                };
                assert!(matches!(e0.expr, ScalarExpr::FuncCall { .. }));
                // No aggregate wrapper.
                assert!(matches!(*input, RelPlan::Scan { .. }));
            }
            other => panic!("expected Project, got {:?}", other),
        }
    }

